@import 'tailwindcss';
@import 'tw-animate-css';

@custom-variant dark (&:is(.dark *));

/* Tema claro (padrão) */
:root {
  --background: #f4f6f8;
  --foreground: #14181d;
  --card: #ffffff;
  --card-foreground: #14181d;
  --popover: #ffffff;
  --popover-foreground: #14181d;
  --surface-2: #eef1f4;
  --primary: #0e9f7a;
  --primary-foreground: #0b0f14;
  --accent-text: #0b7a5e;
  --secondary: #eef1f4;
  --secondary-foreground: #14181d;
  --muted: #eef1f4;
  --muted-foreground: #5f6b76;
  --accent: #eef1f4;
  --accent-foreground: #14181d;
  --destructive: #e5484d;
  --destructive-foreground: #0d1117;
  --border: #dde2e7;
  --input: #dde2e7;
  --ring: #0b7a5e;
  --bad: #e5484d;
  --warn: #f5c518;
  --good: #3dd68c;
  --on-verdict: #0d1117;
  --stage: #dfe4e9;
  --radius: 1rem;
}

/* Tema escuro */
.dark {
  --background: #0d1117;
  --foreground: #e6edf3;
  --card: #161b22;
  --card-foreground: #e6edf3;
  --popover: #161b22;
  --popover-foreground: #e6edf3;
  --surface-2: #21262d;
  --primary: #2fd3a6;
  --primary-foreground: #0d1117;
  --accent-text: #2fd3a6;
  --secondary: #21262d;
  --secondary-foreground: #e6edf3;
  --muted: #21262d;
  --muted-foreground: #8b949e;
  --accent: #21262d;
  --accent-foreground: #e6edf3;
  --destructive: #e5484d;
  --destructive-foreground: #0d1117;
  --border: #30363d;
  --input: #30363d;
  --ring: #2fd3a6;
  --stage: #05070a;
}

@theme inline {
  --font-sans: 'Atkinson Hyperlegible', 'Atkinson Hyperlegible Fallback', system-ui, sans-serif;
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-surface-2: var(--surface-2);
  --color-accent-text: var(--accent-text);
  --color-bad: var(--bad);
  --color-warn: var(--warn);
  --color-good: var(--good);
  --color-on-verdict: var(--on-verdict);
  --color-stage: var(--stage);
  --radius-sm: calc(var(--radius) - 6px);
  --radius-md: calc(var(--radius) - 4px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  button {
    cursor: pointer;
  }
}

/* Ícones Material Symbols (fonte carregada no layout) */
.msr {
  font-family: 'Material Symbols Rounded';
  font-weight: 400;
  font-style: normal;
  display: inline-block;
  width: 1em;
  height: 1em;
  line-height: 1;
  text-transform: none;
  letter-spacing: normal;
  white-space: nowrap;
  direction: ltr;
  overflow: hidden;
  flex-shrink: 0;
  user-select: none;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: 'liga';
}

/* Controle deslizante grande para uso com o dedo */
.big-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 56px;
  background: transparent;
  cursor: pointer;
}
.big-range::-webkit-slider-runnable-track {
  height: 12px;
  border-radius: 9999px;
  background: var(--surface-2);
  border: 1px solid var(--border);
}
.big-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 36px;
  height: 36px;
  margin-top: -13px;
  border-radius: 9999px;
  background: var(--primary);
  border: 4px solid var(--card);
  box-shadow: 0 0 0 2px var(--primary);
}
.big-range::-moz-range-track {
  height: 12px;
  border-radius: 9999px;
  background: var(--surface-2);
  border: 1px solid var(--border);
}
.big-range::-moz-range-thumb {
  width: 28px;
  height: 28px;
  border-radius: 9999px;
  background: var(--primary);
  border: 4px solid var(--card);
  box-shadow: 0 0 0 2px var(--primary);
}
.big-range:focus-visible {
  outline: 2px solid var(--accent-text);
  outline-offset: 2px;
  border-radius: 12px;
}

/* Aviso que some sozinho */
@keyframes shrink {
  from {
    width: 100%;
  }
  to {
    width: 0%;
  }
}
.animate-shrink {
  animation: shrink 8s linear forwards;
}
@media (prefers-reduced-motion: reduce) {
  .animate-shrink {
    animation: none;
    width: 60%;
  }
}

/* Marcadores do mapa (Leaflet) */
.leaflet-container {
  font-family: inherit;
  background: var(--card);
}
.leaflet-control-attribution {
  font-size: 11px !important;
}
.radar-pin {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 9999px;
  border: 3px solid #ffffff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.45);
  color: #0d1117;
  transition: transform 0.15s ease;
}
.radar-pin.is-selected {
  transform: scale(1.3);
  box-shadow: 0 0 0 4px #0d1117, 0 0 0 7px #2fd3a6;
}
.radar-pin--valeta {
  background: #f5c518;
}
.radar-pin--radar {
  background: #e5484d;
}
.radar-pin--bom {
  background: #3dd68c;
}
.radar-pin--evento {
  background: #e6edf3;
}

import type { Metadata, Viewport } from 'next'
import { Atkinson_Hyperlegible } from 'next/font/google'
import './globals.css'

const _atkinson = Atkinson_Hyperlegible({
  subsets: ['latin'],
  weight: ['400', '700'],
})

export const metadata: Metadata = {
  title: 'Radar Corridas · Protótipo de telas',
  description:
    'Protótipo navegável do app Radar Corridas para motoristas de aplicativo: cartão da oferta, ganhos, mapa, bolinha flutuante e avisos, em tema escuro e claro.',
  generator: 'v0.app',
}

export const viewport: Viewport = {
  themeColor: '#0D1117',
  width: 'device-width',
  initialScale: 1,
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="pt-BR" className="dark bg-background">
      <head>
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link
          rel="preconnect"
          href="https://fonts.gstatic.com"
          crossOrigin="anonymous"
        />
        <link
          rel="stylesheet"
          href="https://fonts.googleapis.com/css2?family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,400..700,0..1,0&display=block"
        />
      </head>
      <body className="font-sans antialiased">{children}</body>
    </html>
  )
}

import { cn } from '@/lib/utils'

type IconProps = {
  name: string
  size?: number
  fill?: boolean
  className?: string
}

/** Material Symbols (Rounded). Sempre decorativo: o significado vem do texto ao lado. */
export function Icon({ name, size = 24, fill = false, className }: IconProps) {
  return (
    <span
      aria-hidden="true"
      className={cn('msr', className)}
      style={{
        fontSize: size,
        fontVariationSettings: `'FILL' ${fill ? 1 : 0}, 'wght' 500, 'GRAD' 0, 'opsz' ${Math.min(48, Math.max(20, size))}`,
      }}
    >
      {name}
    </span>
  )
}

import type { ButtonHTMLAttributes, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { Icon } from './icon'
import type { Verdict } from './config'

export const VERDICT: Record<
  Verdict,
  {
    label: string
    short: string
    icon: string
    dotIcon: string
    fill: string
    border: string
  }
> = {
  bom: {
    label: 'Corrida boa',
    short: 'Bom',
    icon: 'check_circle',
    dotIcon: 'check',
    fill: 'bg-good',
    border: 'border-good',
  },
  medio: {
    label: 'Corrida média',
    short: 'Médio',
    icon: 'error',
    dotIcon: 'remove',
    fill: 'bg-warn',
    border: 'border-warn',
  },
  ruim: {
    label: 'Corrida ruim',
    short: 'Ruim',
    icon: 'cancel',
    dotIcon: 'close',
    fill: 'bg-bad',
    border: 'border-bad',
  },
}

/** Bolinha do veredito: cor + ícone dentro + texto para leitor de tela. */
export function VerdictDot({
  verdict,
  size = 32,
}: {
  verdict: Verdict
  size?: number
}) {
  const v = VERDICT[verdict]
  return (
    <span
      className={cn(
        'grid shrink-0 place-items-center rounded-full text-on-verdict',
        v.fill,
      )}
      style={{ width: size, height: size }}
    >
      <Icon name={v.dotIcon} size={size * 0.68} />
      <span className="sr-only">{v.short}</span>
    </span>
  )
}

type ActionButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: 'primary' | 'secondary' | 'ghost'
  size?: 'md' | 'lg'
  icon?: string
}

const BUTTON_VARIANTS = {
  primary: 'bg-primary text-primary-foreground',
  secondary: 'border-2 border-border bg-surface-2 text-foreground',
  ghost: 'text-foreground',
}

export function ActionButton({
  variant = 'primary',
  size = 'md',
  icon,
  className,
  children,
  ...rest
}: ActionButtonProps) {
  return (
    <button
      type="button"
      className={cn(
        'inline-flex w-full items-center justify-center gap-2 rounded-2xl px-4 text-lg font-bold transition-transform focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-text active:scale-[0.98] disabled:opacity-60',
        size === 'lg' ? 'min-h-16 text-xl' : 'min-h-14',
        BUTTON_VARIANTS[variant],
        className,
      )}
      {...rest}
    >
      {icon && <Icon name={icon} size={26} />}
      {children}
    </button>
  )
}

export function SwitchVisual({ checked }: { checked: boolean }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        'relative h-9 w-16 shrink-0 rounded-full border-2 transition-colors',
        checked
          ? 'border-primary bg-primary'
          : 'border-muted-foreground bg-surface-2',
      )}
    >
      <span
        className={cn(
          'absolute top-0.5 grid size-7 place-items-center rounded-full transition-all',
          checked
            ? 'left-[30px] bg-primary-foreground text-accent-text'
            : 'left-0.5 bg-muted-foreground text-card',
        )}
      >
        <Icon name={checked ? 'check' : 'close'} size={18} />
      </span>
    </span>
  )
}

const ROW =
  'flex min-h-16 w-full items-center gap-4 px-4 py-3 text-left focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent-text active:bg-surface-2'

function RowIcon({ name }: { name: string }) {
  return (
    <span className="grid size-11 shrink-0 place-items-center rounded-full bg-surface-2 text-foreground">
      <Icon name={name} size={24} />
    </span>
  )
}

export function NavRow({
  icon,
  title,
  value,
  onClick,
  chevron = true,
}: {
  icon: string
  title: string
  value?: string
  onClick?: () => void
  chevron?: boolean
}) {
  return (
    <button type="button" onClick={onClick} className={ROW}>
      <RowIcon name={icon} />
      <span className="min-w-0 flex-1">
        <span className="block text-lg font-bold leading-snug">{title}</span>
        {value && (
          <span className="block text-base text-muted-foreground">{value}</span>
        )}
      </span>
      {chevron && (
        <Icon name="chevron_right" size={28} className="text-muted-foreground" />
      )}
    </button>
  )
}

export function ToggleRow({
  icon,
  title,
  description,
  checked,
  onChange,
}: {
  icon: string
  title: string
  description?: string
  checked: boolean
  onChange: (v: boolean) => void
}) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      onClick={() => onChange(!checked)}
      className={ROW}
    >
      <RowIcon name={icon} />
      <span className="min-w-0 flex-1">
        <span className="block text-lg font-bold leading-snug">{title}</span>
        <span className="block text-base text-muted-foreground">
          {checked ? 'Ligado' : 'Desligado'}
          {description ? ` · ${description}` : ''}
        </span>
      </span>
      <SwitchVisual checked={checked} />
    </button>
  )
}

export function Group({
  title,
  children,
}: {
  title: string
  children: ReactNode
}) {
  return (
    <section className="mt-7">
      <h2 className="px-1 pb-2 text-lg font-bold text-muted-foreground">
        {title}
      </h2>
      <div className="divide-y divide-border overflow-hidden rounded-2xl border border-border bg-card">
        {children}
      </div>
    </section>
  )
}

export function Segmented<T extends string>({
  value,
  onChange,
  options,
  label,
}: {
  value: T
  onChange: (v: T) => void
  options: { id: T; label: string; icon: string }[]
  label: string
}) {
  return (
    <div
      role="radiogroup"
      aria-label={label}
      className="grid gap-1 rounded-2xl bg-surface-2 p-1"
      style={{ gridTemplateColumns: `repeat(${options.length}, minmax(0, 1fr))` }}
    >
      {options.map((o) => {
        const active = o.id === value
        return (
          <button
            key={o.id}
            type="button"
            role="radio"
            aria-checked={active}
            onClick={() => onChange(o.id)}
            className={cn(
              'flex min-h-16 flex-col items-center justify-center gap-0.5 rounded-xl px-1 text-base font-bold focus-visible:outline-2 focus-visible:outline-accent-text',
              active
                ? 'bg-primary text-primary-foreground'
                : 'text-foreground',
            )}
          >
            <Icon name={o.icon} size={24} fill={active} />
            {o.label}
          </button>
        )
      })}
    </div>
  )
}

export function Skeleton({ className }: { className?: string }) {
  return (
    <div
      aria-hidden="true"
      className={cn('animate-pulse rounded-2xl bg-surface-2', className)}
    />
  )
}

export function LoadingBlock({
  label,
  rows = 3,
}: {
  label: string
  rows?: number
}) {
  return (
    <div role="status" aria-live="polite" className="flex flex-col gap-4 px-4 pt-4">
      <div className="flex items-center gap-3 text-lg font-bold">
        <Icon name="progress_activity" size={32} className="animate-spin text-accent-text" />
        {label}
      </div>
      {Array.from({ length: rows }).map((_, i) => (
        <Skeleton key={i} className="h-24" />
      ))}
    </div>
  )
}

export function StateMessage({
  icon,
  title,
  text,
  action,
  tone = 'neutral',
  className,
}: {
  icon: string
  title: string
  text?: string
  action?: ReactNode
  tone?: 'neutral' | 'error' | 'warn'
  className?: string
}) {
  return (
    <div
      role={tone === 'error' ? 'alert' : 'status'}
      className={cn(
        'flex flex-col items-center gap-3 rounded-3xl border border-border bg-card px-6 py-8 text-center',
        className,
      )}
    >
      <span
        className={cn(
          'grid size-20 place-items-center rounded-full',
          tone === 'error' && 'bg-bad text-on-verdict',
          tone === 'warn' && 'bg-warn text-on-verdict',
          tone === 'neutral' && 'bg-surface-2 text-foreground',
        )}
      >
        <Icon name={icon} size={44} />
      </span>
      <h2 className="text-balance text-2xl font-bold leading-tight">{title}</h2>
      {text && (
        <p className="text-pretty text-lg leading-relaxed text-muted-foreground">
          {text}
        </p>
      )}
      {action && <div className="mt-2 w-full">{action}</div>}
    </div>
  )
}

export function ErrorState({
  title,
  text,
  onRetry,
}: {
  title: string
  text?: string
  onRetry: () => void
}) {
  return (
    <div className="px-4 pt-4">
      <StateMessage
        tone="error"
        icon="cloud_off"
        title={title}
        text={text ?? 'Confira a internet e tente de novo.'}
        action={
          <ActionButton icon="refresh" onClick={onRetry}>
            Tentar de novo
          </ActionButton>
        }
      />
    </div>
  )
}

export function ScreenHeader({
  title,
  subtitle,
  right,
}: {
  title: string
  subtitle?: string
  right?: ReactNode
}) {
  return (
    <header className="flex items-start justify-between gap-3 px-5 pb-3 pt-3">
      <div className="min-w-0">
        <h1 className="text-[32px] font-bold leading-tight">{title}</h1>
        {subtitle && (
          <p className="text-base text-muted-foreground">{subtitle}</p>
        )}
      </div>
      {right}
    </header>
  )
}

import type { ReactNode } from 'react'
import { Icon } from './icon'

export const PHONE_W = 410
export const PHONE_H = 864

function StatusBar() {
  return (
    <div className="flex h-9 shrink-0 items-center justify-between px-6 text-base font-bold">
      <span>21:42</span>
      <span className="flex items-center gap-1.5">
        <Icon name="wifi" size={20} fill />
        <Icon name="signal_cellular_alt" size={20} fill />
        <Icon name="battery_5_bar" size={20} fill />
      </span>
    </div>
  )
}

/** Moldura Android de 390x844, escalada para caber na janela. */
export function PhoneFrame({
  scale,
  children,
}: {
  scale: number
  children: ReactNode
}) {
  return (
    <div style={{ width: PHONE_W * scale, height: PHONE_H * scale }}>
      <div
        style={{
          width: PHONE_W,
          height: PHONE_H,
          transform: `scale(${scale})`,
          transformOrigin: 'top left',
        }}
        className="rounded-[56px] bg-black p-[10px] shadow-2xl ring-1 ring-border"
      >
        <div className="relative flex h-[844px] w-[390px] flex-col overflow-hidden rounded-[46px] bg-background text-foreground">
          <StatusBar />
          {children}
          <div
            aria-hidden="true"
            className="pointer-events-none absolute bottom-2 left-1/2 h-1.5 w-32 -translate-x-1/2 rounded-full bg-foreground/70"
          />
        </div>
      </div>
    </div>
  )
}

import { cn } from '@/lib/utils'
import { Icon } from './icon'
import type { ScreenId } from './config'

const ITEMS: { id: ScreenId; label: string; icon: string }[] = [
  { id: 'inicio', label: 'Início', icon: 'home' },
  { id: 'ganhos', label: 'Ganhos', icon: 'payments' },
  { id: 'mapa', label: 'Mapa', icon: 'map' },
  { id: 'ajustes', label: 'Ajustes', icon: 'settings' },
]

export function BottomNav({
  active,
  go,
}: {
  active: ScreenId
  go: (s: ScreenId) => void
}) {
  return (
    <nav
      aria-label="Navegação principal"
      className="grid shrink-0 grid-cols-4 border-t border-border bg-card px-2 pb-6 pt-2"
    >
      {ITEMS.map((item) => {
        const isActive = item.id === active
        return (
          <button
            key={item.id}
            type="button"
            onClick={() => go(item.id)}
            aria-current={isActive ? 'page' : undefined}
            className="flex min-h-16 flex-col items-center justify-center gap-1 rounded-2xl focus-visible:outline-2 focus-visible:outline-accent-text"
          >
            <span
              className={cn(
                'grid h-8 w-16 place-items-center rounded-full transition-colors',
                isActive
                  ? 'bg-primary text-primary-foreground'
                  : 'text-foreground',
              )}
            >
              <Icon name={item.icon} size={26} fill={isActive} />
            </span>
            <span
              className={cn(
                'text-base leading-none',
                isActive ? 'font-bold' : 'text-muted-foreground',
              )}
            >
              {item.label}
            </span>
          </button>
        )
      })}
    </nav>
  )
}

