      { name: 'R$/min', value: 'R$ 0,63', goal: 'meta R$ 0,60', verdict: 'bom' },
      { name: 'Lucro líquido', value: 'R$ 8,88', goal: 'meta R$ 10,00', verdict: 'medio' },
